// Populate the project list (already provided in your code)
function populateProjectList(projects) {
  const projectList = root_element.querySelector(".project-list");
  const detailsDiv = root_element.querySelector(".details-scroll");
  const detailsDivFixed = root_element.querySelector(".details-fixed");

  if (!projectList || !detailsDiv || !detailsDivFixed) {
    console.error(".project-list or .details element not found in the DOM.");
    return;
  }

  projectList.innerHTML = ""; // Clear the existing content

  // Check if there are any projects
  if (projects.length === 0) {
    const noRecordsMessage = document.createElement("li");
    noRecordsMessage.textContent = "No records found";
    noRecordsMessage.style.color = "red";
    noRecordsMessage.style.textAlign = "center";
    projectList.appendChild(noRecordsMessage);
    return;
  }

  projects.forEach((project, index) => {
    const statusColor =
      project.custom_branch_status === "Not Started" ? "#007bff" :
      project.custom_branch_status === "Under Development" ? "#E49B0F" :
      project.custom_branch_status === "Live" ? "#28a745" :
      "#000";

    const li = document.createElement("li");
    li.classList.add("project-item");
    li.setAttribute("data-status-color", statusColor);

    // No see-project button here anymore
    li.innerHTML = `
      <div class="project-info">
        <div style="display: flex; align-items: center;">
          <img src="/assets/sahayog/images/sahalogo.svg" alt="Logo" style="width: 30px; height: 30px; margin-right: 10px; vertical-align: middle;">
          <span>${project.project_name}</span>
        </div>
        <span class="status" style="color: ${statusColor}; border:1px solid ${statusColor}; text-shadow: 0.5px 0.5px 0.5px rgba(0, 0, 0, 0.5);">
          ${project.custom_branch_status}
        </span>
      </div>
      <div class="project-details">
        <span style='float: left;'>
          <span style="color: #28a745; font-size: 20px;">&#8226;</span> ${project.custom_zone}
          <span style="color: #28a745; font-size: 20px;">&#8226;</span> ${project.custom_region}
          <span style="color: #28a745; font-size: 20px;">&#8226;</span> ${project.custom_division}
        </span>
      </div>
    `;

    projectList.appendChild(li);

    // Add a separator <hr> after each <li>, except the last one
    if (index < projects.length - 1) {
      const hr = document.createElement("hr");
      hr.style.border = "1px solid #ccc";
      hr.style.margin = "5px 0";
      projectList.appendChild(hr);
    }

    li.addEventListener("click", function () {
      console.log(`Project clicked: ${project.project_name}`);

      const allItems = projectList.querySelectorAll(".project-item");
      allItems.forEach((item) => {
        item.classList.remove("selected");
        item.style.border = "";
        item.style.borderLeft = "";
      });

      li.classList.add("selected");
      li.style.border = `1px solid ${statusColor}`;
      li.style.borderLeft = `5px solid ${statusColor}`;

      // Set details section with link-style button
      detailsDivFixed.innerHTML = `
        <div style="display: flex; justify-content: space-between; align-items: center;">
          <b><span style='font-size: 20px;'>${project.project_name} - Tasks</span></b>
            <p style="margin-top: 0;">
          <span style='float: right; color: #555;'>
            <span style="color: #28a745;font-size: 20px;">&#8226;</span> ${project.custom_zone} 
            <span style="color: #28a745;font-size: 20px;">&#8226;</span> ${project.custom_region} 
            <span style="color: #28a745;font-size: 20px;">&#8226;</span> ${project.custom_division}
          </span>
        </p>
        </div>
         <a href="#" id="see-project-btn" style="font-size: 12px; color: #007bff; text-decoration: underline; cursor: pointer;">
            See Project
          </a>
          ${project.branch_proposal ? `
              <a href="/app/branch-proposal/${project.branch_proposal}" target="_blank" style="font-size: 12px; margin-left: 10px; color: #17a2b8; text-decoration: underline; cursor: pointer;">
                See Branch Proposal
              </a>` : ''}
                <p>
          <div style="display: flex; justify-content: space-between; align-items: center;">
            <span style="font-size: 14px; color: #555;" class="percent-text">${project.percent_complete}% Completed</span>
            <span class="status" style="color: ${statusColor}; border:1px solid ${statusColor}; text-shadow: 0.5px 0.5px 0.5px rgba(0,0,0,0.5);">
              ${project.custom_branch_status}
            </span>
          </div>
          <div style="width: 100%; background-color: #ddd; border-radius: 10px; height: 10px;">
            <div class="progress-bar" style="width: ${project.percent_complete}%; background-color: #009A1E; height: 100%; border-radius: 10px;"></div>
          </div>
        </p>
      `;

      // Add click handler for See Project button
      const seeButton = detailsDivFixed.querySelector("#see-project-btn");
      if (seeButton) {
        seeButton.addEventListener("click", (e) => {
          e.preventDefault(); // Avoid page jump
          e.stopPropagation(); // Don't bubble to project click
          // Optional navigation
          frappe.set_route("Form", "Project", project.name);
        });
      }

      // Fetch tasks for the selected project
        // Fetch tasks for the selected project with delay
        detailsDiv.innerHTML = `<p style="text-align:center; font-size:14px; color:#888;">Loading tasks...</p>`; // Optional visual cue

        setTimeout(() => {
          fetchTasksForProject(project.name, detailsDiv);
        }, 300);

      // Animate the progress bar
      const progressBar = root_element.querySelector(".progress-bar");
      const percentageText = root_element.querySelector(".percent-text");
      animateProgressBarAndText(progressBar, percentageText, project.percent_complete);
    });
  });

  console.log("Project list populated successfully.");
}

function fetchTasksForProject(projectName, detailsDiv) {
  frappe.call({
    method: "sahayog.patches.fixtures.get_projects_and_tasks.get_all_tasks", // Correct path
    args: {
      name: projectName  // Pass the project name to the server-side function
    },
    callback: function (response) {
      if (response.message) {
        console.log("Tasks for project:", projectName, response.message);
        displayTaskList(response.message, detailsDiv);
      } else {
        console.error("No tasks found for this project.");
      }
    },
    error: function (error) {
      console.error("Error fetching tasks:", error);
    },
  });
}

function displayTaskList(tasks, detailsDiv) {
  detailsDiv.innerHTML = `<ul class="tasks"></ul>`;
  const taskList = detailsDiv.querySelector(".tasks");

  const base_url = window.location.origin;

  // Sort tasks
  tasks.sort((a, b) => {
    const indexA = parseInt(a.subject.match(/\d+/));
    const indexB = parseInt(b.subject.match(/\d+/));
    return indexA - indexB;
  });

  tasks.forEach((task, index) => {
    const loi_doc_name = `${task.project}-LOI`;
    const loi_pdf_url = `${base_url}/api/method/frappe.utils.print_format.download_pdf?doctype=Letter%20of%20Intent&name=${encodeURIComponent(loi_doc_name)}&format=LOI2&no_letterhead=0&letterhead=Sahayog%20Letter%20Head&settings=%7B%7D&_lang=en`;
    const loi_doc_url = `/app/letter-of-intent?project=${encodeURIComponent(task.project || '')}`;

    const statusColor = 
      task.status === "Open" ? "#FFA500" :
      task.status === "Working" ? "#007BFF" :
      task.status === "Pending Review" ? "#E6B800" :
      task.status === "Overdue" ? "#FF0000" :
      task.status === "Template" ? "#6C757D" :
      task.status === "Completed" ? "#009A1E" :
      task.status === "Cancelled" ? "#DC3545" :
      "#000";

    const formattedDate = formatDate(task.modified);
    const isTask1 = task.subject.trim().toLowerCase() === "acquisition of the property";
    const isTask2 = task.subject.trim().toLowerCase() === "letter of intent";
    const isAgreementTask = task.subject.trim().toLowerCase() === "agreement and handover";
    const isHiringTask = task.subject.trim().toLowerCase() === "manpower recruitment";
    const isInfraTask = task.subject.trim().toLowerCase() === "infrastructure development work";
    const isHardwareTask = task.subject.trim().toLowerCase() === "it hardware installation";
    const isSoftwareTask = task.subject.trim().toLowerCase() === "it software installation";
    const isTrainingTask = task.subject.trim().toLowerCase() === "licence to operate";




    let extraLinks = "";

    if (isTask1 && task.location_details_table) {
      extraLinks += `
        <span onclick="event.stopPropagation(); showLocationDetails(${JSON.stringify(task.location_details_table).replace(/"/g, '&quot;')})"
              class="task-extra-link" style="cursor:crosshair; font-size: 12px; margin-left: 10px; color: #e83e8c; text-decoration: underline;">
          [Location Details]
        </span>
      `;
    }

    if (isTask2) {
      extraLinks += `
        <a href="${loi_pdf_url}" target="_blank" class="task-extra-link" onclick="event.stopPropagation()" style="cursor:crosshair; font-size: 12px; margin-left: 10px; color: #007bff; text-decoration: underline;">[LOI PDF]</a>
        <a href="${loi_doc_url}" target="_blank" class="task-extra-link" onclick="event.stopPropagation()" style="cursor:crosshair; font-size: 12px; margin-left: 6px; color: #28a745; text-decoration: underline;">[Open LOI]</a>
      `;
    }

    if (isAgreementTask && task.custom_agreement) {
      extraLinks += `
        <a href="${task.custom_agreement}" target="_blank" class="task-extra-link" onclick="event.stopPropagation()" style="cursor:crosshair; font-size: 12px; margin-left: 10px; color: #17a2b8; text-decoration: underline;">[View Attach]</a>
      `;
    }

    if (isHiringTask && task.manpower_recruitment_table) {
      extraLinks += `
        <span onclick="event.stopPropagation(); showHiringTable(${JSON.stringify(task.manpower_recruitment_table).replace(/"/g, '&quot;')})" 
            class="task-extra-link"  style="cursor:crosshair; font-size: 12px; margin-left: 10px; color: #6f42c1; text-decoration: underline;">
          [Hiring Table]
        </span>
      `;
    }

    if (isInfraTask && task.infrastructure_development_table) {
      extraLinks += `
        <span onclick="event.stopPropagation(); showInfraTable(${JSON.stringify(task.infrastructure_development_table).replace(/"/g, '&quot;')})" 
            class="task-extra-link"  style="cursor:crosshair; font-size: 12px; margin-left: 10px; color: #6f42c1; text-decoration: underline;">
          [Infra Table]
        </span>
      `;
    }

     if (isTrainingTask && task.lto_training_table) {
      extraLinks += `
        <span onclick="event.stopPropagation(); showTrainingTable(${JSON.stringify(task.lto_training_table).replace(/"/g, '&quot;')})" 
            class="task-extra-link"  style="cursor:crosshair; font-size: 12px; margin-left: 10px; color: #6f42c1; text-decoration: underline;">
          [Training Table]
        </span>
      `;
    }

    if ((isHardwareTask || isSoftwareTask) && task.it_checklist_table) {
      extraLinks += `
        <span onclick="event.stopPropagation(); showITChecklist(${JSON.stringify(task.it_checklist_table).replace(/"/g, '&quot;')})" 
            class="task-extra-link"  style="cursor:crosshair; font-size: 12px; margin-left: 10px; color: #007bff; text-decoration: underline;">
          [View Checklist]
        </span>
      `;
    }


    const li = document.createElement("li");

    li.innerHTML = `
      <p>
        <b>
          <span style='font-size:16px;'>${task.custom_sequence}) ${task.subject}</span>
          ${extraLinks}
        </b><br>
        <span style='color:#005570;font-size:12px;' title="Expected Start Date">${task.exp_start_date}</span> 
        <span class="loading-indicator" style='font-size:16px;'></span> 
        <span style='color:#5A892E;font-size:12px;' title="Expected End Date">${task.exp_end_date}</span>
      </p>
      <p>
        <span class="status" style='font-size:16px;float: right;color:${statusColor};text-shadow: 1px 1px 1px rgba(0, 0, 0, 0.5);'>${task.status}</span><br>
        <span class="assigned-to" style='font-size:10px;float: right;'><i>last updated - ${formattedDate}</i></span>
      </p>
    `;

    taskList.appendChild(li);

    if (index < tasks.length - 1) {
      const hr = document.createElement("hr");
      hr.style.border = "1px solid #ccc";
      hr.style.margin = "5px 0 5px -10px";
      hr.style.width = "105%";
      taskList.appendChild(hr);
    }

    li.addEventListener("click", function () {
      const taskUrl = `/app/task/${task.name}`;
      window.open(taskUrl, "_blank");
    });
  });

  console.log("Tasks displayed and sorted successfully.");
}

