window.showLocationDetails = function(tableData) {
  if (!tableData || tableData.length === 0) {
    frappe.msgprint("No location details available.");
    return;
  }

  // Group by location_name, estimate_rent, and status
  const groupedData = {};
  tableData.forEach(row => {
    const key = `${row.location_name}-${row.estimate_rent}-${row.status}`;
    if (!groupedData[key]) {
      groupedData[key] = {
        location_name: row.location_name,
        rent_per_month: row.rent_per_month,
        status: row.status,
        images: []
      };
    }
    if (row.location_image) {
      groupedData[key].images.push(row.location_image);
    }
  });

  // Construct table rows
  const tableRows = Object.values(groupedData).map(row => {
    const imageHtml = row.images.length > 0
      ? row.images.map(img =>
          `<a href="${img}" target="_blank" style="margin-right:2px;">
            <img src="${img}" class="media-thumbnail" />
          </a>`
        ).join("")
      : "-";

    // Status CSS class based on status value
    const statusClass = row.status
      ? `status-${row.status.toLowerCase().replace(/\s+/g, "-")}`
      : "";

    return `
      <tr>
        <td>${row.location_name || "-"}</td>
        <td style="max-width: 300px;">${imageHtml}</td>
        <td>₹ ${parseInt(row.rent_per_month).toLocaleString("en-IN")}</td>
        <td><span class="status-badge ${statusClass}">${row.status || "-"}</span></td>
      </tr>
    `;
  }).join("");

  const html = `
    <style>
      .media-thumbnail {
        width: 40px;
        height: 40px;
        border-radius: 8px;
        object-fit: cover;
        border: 1px solid #ccc;
        transition: all 0.2s ease-in-out;
      }
      .media-thumbnail:hover {
        transform: translateY(-2px);
        box-shadow: 0 3px 10px rgba(0,0,0,0.1);
        border-color: #5e64ff;
      }

      .status-badge {
        padding: 4px 8px;
        border-radius: 6px;
        color: white;
        font-size: 12px;
        font-weight: 500;
        display: inline-block;
        text-transform: capitalize;
      }

      .status-approved {
        background-color: #28a745;
      }

      .status-pending {
       background-color: #adb5bd; /* Bootstrap-ish muted gray */
       color: #fff;
      }

      .status-rejected {
        background-color: #dc3545;
      }

      /* Add more if needed */
    </style>

    <div style="overflow-x: auto;">
      <table class="table table-bordered">
        <thead>
          <tr>
            <th>Location Name</th>
            <th style="width: 400px;">Location Images</th>
            <th>Rent/Month</th>
            <th>Status</th>
          </tr>
        </thead>
        <tbody>${tableRows}</tbody>
      </table>
    </div>
  `;

  frappe.msgprint({
    title: "Location Details",
    indicator: "blue",
    message: html,
    wide: true
  });
};

window.showITChecklist = function(tableData) {
  if (!tableData || tableData.length === 0) {
    frappe.msgprint("No checklist data available.");
    return;
  }

  // Count statuses
  const total = tableData.length;
  const pending = tableData.filter(row => row.status === "Pending").length;
  const inProgress = tableData.filter(row => row.status === "In-Progress").length;
  const completed = tableData.filter(row => row.status === "Completed").length;

  // Generate table rows
  const tableRows = tableData.map(row => {
    let statusClass = '';
    if (row.status === "Pending") statusClass = "badge-pending";
    else if (row.status === "In-Progress") statusClass = "badge-in-progress";
    else if (row.status === "Completed") statusClass = "badge-completed";

    return `
      <tr>
        <td>${row.activity || "-"}</td>
        <td>${row.category || "-"}</td>
        <td><span class="status-badge ${statusClass}">${row.status || "-"}</span></td>
      </tr>
    `;
  }).join("");

  // Build HTML content
  const html = `
    <style>
      .status-badge {
        padding: 4px 8px;
