(function () {
    const chartContainer = root_element.querySelector("#product-type-chart-container");
    if (!chartContainer) return;

    const chartElement = root_element.querySelector("#product-type-chart");
    if (!chartElement) return;

    // Destroy old chart instance if it exists
    if (chartElement.chartInstance) chartElement.chartInstance.destroy();

    function loadChartJS(callback) {
        if (typeof Chart !== "undefined") {
            callback();
            return;
        }
        const script = document.createElement("script");
        script.src = "https://cdn.jsdelivr.net/npm/chart.js";
        script.onload = callback;
        document.head.appendChild(script);
    }

    loadChartJS(() => {

        // STEP 1: Fetch all products
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Product",
                fields: ["name", "product_type", "product_name"],
                limit_page_length: 1000
            },
            callback: function (productResponse) {
                const products = productResponse.message || [];
                if (products.length === 0) {
                    chartContainer.innerHTML = "<p style='text-align:center;'>No product records found</p>";
                    return;
                }

                // STEP 2: Fetch lead counts from backend
                frappe.call({
                    method: "sahayog.scrm.api.sahayog_crm_dashboard.get_product_lead_counts",
                    callback: function (leadResponse) {
                        const leadCountMap = leadResponse.message || {};

                        // STEP 3: Prepare chart datasets
                        const allProductTypes = ["SBA", "CAA", "ODA", "TDA", "LAA", "OAB", "OAP", "INSURANCE", "AGENT"];
                        const pastelColors = [
                            "#76c7c0", "#a4d4ae", "#f7b267", "#f28b82", "#d7aefb",
                            "#aec6cf", "#ffb347", "#b39eb5", "#77dd77", "#ff6961"
                        ];

                        const productColorMap = {};
                        let colorIndex = 0;
                        const uniqueNames = Array.from(new Set(products.map(p => p.product_name)));
                        uniqueNames.forEach(name => {
                            productColorMap[name] = pastelColors[colorIndex % pastelColors.length];
                            colorIndex++;
                        });

                        // Create datasets and calculate total leads per product type
                        const datasets = [];
                        const typeLeadTotals = {}; // keep sum of leads per type

                        allProductTypes.forEach((type, typeIndex) => {
                            const productsOfType = products.filter(p => p.product_type === type);
                            let typeTotal = 0;

                            productsOfType.forEach(prod => {
                                const leadCount = leadCountMap[prod.name] || 0;
                                typeTotal += leadCount;

                                if (leadCount > 0) { // ✅ only include products with leads
                                    const dataArray = Array(allProductTypes.length).fill(0);
                                    dataArray[typeIndex] = leadCount;

                                    datasets.push({
                                        label: prod.product_name,
                                        product_code: prod.name,
                                        product_type: prod.product_type,
                                        lead_count: leadCount,
                                        data: dataArray,
                                        backgroundColor: productColorMap[prod.product_name]
                                    });
                                }
                            });

                            typeLeadTotals[type] = typeTotal;
                        });

                        // ✅ Filter out product types that have zero total leads
                        const productTypes = allProductTypes.filter(type => typeLeadTotals[type] > 0);

                        // If no types left, show message
                        if (productTypes.length === 0) {
                            chartContainer.innerHTML = "<p style='text-align:center;'>No lead data available</p>";
                            return;
                        }

                        // Filter datasets accordingly (only those belonging to valid types)
                        const filteredDatasets = datasets.map(ds => {
                            const dataArray = [];
                            productTypes.forEach(type => {
                                dataArray.push(
                                    ds.product_type === type ? ds.lead_count : 0
                                );
                            });
                            return { ...ds, data: dataArray };
                        });

                        // STEP 4: Adjust chart height dynamically
                        const totalProducts = filteredDatasets.length;
                        const height = totalProducts > 50 ? "800px" : totalProducts > 20 ? "600px" : "400px";
                        chartContainer.style.height = height;

                        // STEP 5: Calculate suggested max for better spacing
                        const maxLeadCount = Math.max(...filteredDatasets.map(d => d.lead_count));
                        const suggestedMax = Math.ceil(maxLeadCount * 1.2);

                        // STEP 6: Render chart
                        const ctx = chartElement.getContext("2d");
                        chartElement.chartInstance = new Chart(ctx, {
                            type: "bar",
                            data: { labels: productTypes, datasets: filteredDatasets },
                            options: {
                                responsive: true,
                                maintainAspectRatio: false,
                                plugins: {
                                    tooltip: {
                                        callbacks: {
                                            label: function (context) {
                                                const code = context.dataset.product_code || "";
                                                const name = context.dataset.label || "";
                                                const count = context.dataset.lead_count || 0;
                                                return `${code} : ${name} (Leads: ${count})`;
                                            }
                                        }
                                    },
                                    legend: { display: false },
                                    title: {
                                        display: true,
                                        text: "Products per Product Type (with Lead Counts)",
                                        font: { size: 18 }
                                    }
                                },
                                scales: {
                                    x: {
                                        stacked: true,
                                        title: { display: true, text: "Product Type" },
                                        grid: { display: false } // ❌ Hide vertical grid lines
                                    },
                                    y: {
                                        stacked: true,
                                        beginAtZero: true,
                                        suggestedMax: suggestedMax,
                                        title: { display: true, text: "Total Leads" },
                                        ticks: { autoSkip: true },
                                        grid: {
                                            display: true,
                                            color: "rgba(0, 0, 0, 0.05)", // 🌫️ Very light horizontal lines
                                            drawBorder: false,
                                            lineWidth: 1
                                        }
                                    }
                                }
                            }
                        });
                    }
                });
            }
        });
    });
})();

(function () {
    const root = root_element || document;
    let userRole = '';
    let pendingStart = 0;
    let recentStart = 0;

    const upd = (id, val) => { 
        const el = root.querySelector(`#${id}`); 
        if (el) el.innerText = val ?? 0; 
    };

    const renderRows = (list) => list.map(i => `
                        <tr onclick="frappe.set_route('Form', 'My Audits', '${i.name}')">
                            <td>${i.sr_no}</td>
                            <td><span class='t-id'>${i.name}</span></td>
                            <td>${i.emp_branch || '---'}</td>
                            <td>${i.audit_query_subject_box || '---'}</td>
                            <td>${i.emp_division || '---'}</td>
                            <td><span class='t-status ${i.status === 'Pending' ? 'pending' : (i.status === 'Close' ? 'close' : '')}'>${i.status || '---'}</span></td>
                            <td><span class='t-risk ${(i.risk || 'Normal').toLowerCase()}'>${i.risk || 'Normal'}</span></td>
                            <td>${i.aging || 0}</td>
                        </tr>`).join('');

    window.load_more_data = (type) => {
        const args = {
            pending_start: type === 'pending' ? pendingStart + 10 : pendingStart,
            recent_start: type === 'recent' ? recentStart + 10 : recentStart
        };
        frappe.call({
            method: 'audit_management.audit_management.dashboard.get_dashboard_stats',
            args: args,
            callback: function (r) {
                if (!r.message?.success) return;
                const d = r.message;
                if (type === 'pending') {
                    pendingStart += 10;
                    root.querySelector('#stage-items').insertAdjacentHTML('beforeend', renderRows(d.pending_list));
                    const btn = root.querySelector('#pending-more-btn');
                    if (btn) btn.style.display = d.has_more_pending ? 'flex' : 'none';
                } else {
                    recentStart += 10;
                    root.querySelector('#activity-body').insertAdjacentHTML('beforeend', renderRows(d.recent_list));
                    const btn = root.querySelector('#recent-more-btn');
                    if (btn) btn.style.display = d.has_more_recent ? 'flex' : 'none';
                }
            }
        });
    };

    function refresh() {
        pendingStart = 0; recentStart = 0;
        frappe.call({
            method: 'audit_management.audit_management.dashboard.get_dashboard_stats',
            args: { pending_start: 0, recent_start: 0 },
            callback: function (r) {
                if (!r.message?.success) return;
                const d = r.message; 

                userRole = d.role_type;

                // Visibility Control
                const masterCapsules = root.querySelector('.master-capsule-container');
                const draftCard = root.querySelector('#draft-card');

                if (userRole === 'stage_user') {
                    if (masterCapsules) masterCapsules.style.display = 'none';
                    if (draftCard) draftCard.style.display = 'none';
                } else {
                    if (masterCapsules) masterCapsules.style.display = 'flex';
                    if (draftCard) draftCard.style.display = 'block';
                }


                if (userRole === 'stage_user') {
                    upd('val-pending', d.pending_for_me); upd('lbl-pending', 'Pending Me');
                    upd('val-closed', d.responded_by_me); upd('lbl-closed', 'Responded');
                } else {
                    upd('val-draft', d.draft_count);
                    upd('val-pending', d.total_pending); upd('lbl-pending', 'Total Pending');
                    upd('val-closed', d.closed_count); upd('lbl-closed', 'Closed');
                }

                const stageView = root.querySelector('#stage-view');
                const stageItems = root.querySelector('#stage-items');
                const pendingMore = root.querySelector('#pending-more-btn');

                if (d.pending_list && d.pending_list.length > 0) {
                    stageView.style.display = 'block';
                    stageItems.innerHTML = renderRows(d.pending_list);
                    if (pendingMore) pendingMore.style.display = d.has_more_pending ? 'flex' : 'none';
                } else {
                    stageView.style.display = 'none';
                }

                const managerView = root.querySelector('#manager-view');
                const activityBody = root.querySelector('#activity-body');
                const recentMore = root.querySelector('#recent-more-btn');

                if (userRole !== 'stage_user' && d.recent_list && d.recent_list.length > 0) {
                    managerView.style.display = 'block';
                    activityBody.innerHTML = renderRows(d.recent_list);
                    if (recentMore) recentMore.style.display = d.has_more_recent ? 'flex' : 'none';
                } else {
                    managerView.style.display = 'none';
                }
            }
        });
    }

    window.handle_pending_click = () => { 
        if (userRole === 'stage_user') frappe.call({ method: 'audit_management.audit_management.dashboard.get_my_pending_records', callback: r => r.message?.length && frappe.set_route('List', 'My Audits', { name: ['in', r.message] }) });
        else frappe.set_route('List', 'My Audits', { status: 'Pending' });
    };
    window.handle_closed_click = () => { 
        if (userRole === 'stage_user') frappe.call({ method: 'audit_management.audit_management.dashboard.get_my_responded_records', callback: r => r.message?.length && frappe.set_route('List', 'My Audits', { name: ['in', r.message] }) });
        else frappe.set_route('List', 'My Audits', { status: 'Close' });
    };

    $(document).on('workspace_render', refresh); refresh();
})();

