.live-dot { width: 8px; height: 8px; background: #22c55e; border-radius: 50%; box-shadow: 0 0 10px rgba(34, 197, 94, 0.4); }

.master-capsule-container { display: flex; gap: 8px; flex-wrap: wrap; }
.master-capsule { background: #ffffff; padding: 6px 14px; border-radius: 50px; border: 1px solid #e2e8f0; display: flex; align-items: center; gap: 8px; cursor: pointer; transition: 0.2s; box-shadow: 0 1px 2px rgba(0,0,0,0.05); }
